   341	export function isOpenEnded(q: QuizQuestion): boolean {
   342		if (q.type === "short_answer" || q.type === "transfer") return true;
   343		// Single-blank fill_in is free text; multi-blank fill_in is graded per blank.
   344		if (q.type === "fill_in" && !(q.blanks && q.blanks.length > 0)) return true;
   345		return false;
   346	}
   347	
   348	function isCorrect(q: QuizQuestion, rawAnswer: string): boolean {
   349		if (q.type === "multi_select" && q.correctAnswers) {
   350			const selected = new Set(rawAnswer.split(",").map((s) => s.trim()).filter(Boolean));
   350			const selected = new Set(rawAnswer.split(",").map((s) => s.trim()).filter(Boolean));
   351			return (
   352				q.correctAnswers.length === selected.size &&
   353				q.correctAnswers.every((c) => selected.has(c))
   354			);
   355		}
   356		if (q.type === "fill_in" && q.blanks && q.blanks.length > 0) {
   357			const userAnswers = rawAnswer.split("|").map((s) => s.trim());
   358			const correctAnswers = q.correctAnswers ?? [q.correctAnswer];
   359			if (userAnswers.length !== correctAnswers.length) return false;
   360			return userAnswers.every((a, i) => a.toLowerCase() === correctAnswers[i].trim().toLowerCase());
   361		}
   362		if (isOpenEnded(q)) {
   363			return questionCredit(q, rawAnswer) >= OPEN_ENDED_CREDIT_THRESHOLD;
   364		}
   365		return rawAnswer.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase();
   366	}
