   549	function QuizResultBadge({ correct }: { correct: boolean }) {
   550		return (
   551			<span
   552				className={cx(
   553					css({
   554						display: "inline-flex",
   555						alignItems: "center",
   556						gap: "0.25rem",
   557						borderRadius: "9999px",
   558						border: "1px solid",
   559						padding: "0.125rem 0.5rem",
   560						fontSize: "0.6875rem",
   561						fontWeight: 500,
   562					}),
   563					correct
   564						? css({
   565							borderColor: "rgba(16, 185, 129, 0.5)",
   566							background: "rgba(16, 185, 129, 0.1)",
   567							color: "#047857",
   568							[dark]: { color: "#6ee7b7" },
   569						})
   570						: css({
   590	}: {
   591		question: string;
   592		blanks: { placeholder?: string; hint?: string }[];
   593		answer: string;
   594		onChange: (val: string) => void;
   595		revealed: boolean;
   596		correctAnswers: string[];
   597	}) {
   598		const values = useMemo(() => answer.split("|").map((s) => s.trim()), [answer]);
   599		const parts = useMemo(() => parseQuestionTemplate(question), [question]);
   600		const blankRefs = useRef<(HTMLInputElement | null)[]>([]);
   601	
   602		const setValue = (idx: number, val: string) => {
   603			const next = [...values];
   604			next[idx] = val;
   605			onChange(next.join("|"));
   606		};
   607	
   608		let blankCounter = 0;
   609		return (
   610			<div className={css({ minWidth: 0 })}>
   611				<div className={css({ fontSize: "0.875rem", fontWeight: 500, lineHeight: "1.75rem", overflowWrap: "break-word" })}>
   612					{parts.map((part, idx) => {
   613						if (!part.isBlank) {
   614							return <span key={idx} className={css({ whiteSpace: "pre-wrap", overflowWrap: "break-word" })}>{part.text}</span>;
   615						}
   616						const bIdx = blankCounter++;
   617						const blankDef = blanks[bIdx];
   618						const isCorrect = revealed && values[bIdx]?.trim().toLowerCase() === correctAnswers[bIdx]?.trim().toLowerCase();
   619						const isWrong = revealed && values[bIdx]?.trim() && !isCorrect;
   620						return (
   621							<span key={idx} className={css({ display: "inline-flex", maxWidth: "100%", alignItems: "baseline", gap: "0.25rem", marginInline: "0.25rem", verticalAlign: "baseline" })}>
   622								<input
   623									ref={(el) => { blankRefs.current[bIdx] = el; }}
   624									type="text"
   625									disabled={revealed}
   626									aria-label={blankDef?.hint ? `${blankDef.hint} blank` : `Blank ${bIdx + 1}`}
   627									title={blankDef?.hint}
   628									className={cx(
   629										quizStyles.fieldBase,
   630										css({ display: "inline-block", height: "1.75rem", width: "7rem", paddingInline: "0.5rem", textAlign: "center", [sm]: { width: "10rem" }, "&::placeholder": { color: "color-mix(in srgb, var(--muted-foreground) 50%, transparent)" } }),
   631										isCorrect ? quizStyles.inputCorrect : isWrong ? quizStyles.inputWrong : quizStyles.inputNeutral,
   632									)}
   633									placeholder={blankDef?.placeholder ?? "___"}
   634									value={values[bIdx] ?? ""}
   635									onChange={(e) => setValue(bIdx, e.target.value)}
   636									onKeyDown={(e) => {
   637										if (e.key === "Enter") {
   638											const nextBlank = blankRefs.current[bIdx + 1];
   639											if (nextBlank) nextBlank.focus();
   640										}
   641									}}
   642								/>
   643								{revealed && (
   644									<span className={css({ fontSize: "0.625rem", color: isCorrect ? "#059669" : "var(--destructive)" })}>
   645										{isCorrect ? "✓" : `✗ ${correctAnswers[bIdx] ?? ""}`}
   646									</span>
   647								)}
   648							</span>
   649						);
   650					})}
   651				</div>
   652			</div>
   653		);
   654	}
